param([string]$Project = (Get-Location).Path)
$ErrorActionPreference = "Stop"
function D($s){ [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($s)) }
$ok = $true
function Fix($rel,$pairs){
  $p = Join-Path $Project $rel
  if(-not(Test-Path $p)){ Write-Host "NOT FOUND: $rel (run from the GM-CRM folder or use -Project)"; $script:ok=$false; return }
  $t = [IO.File]::ReadAllText($p); $todo = 0
  foreach($pr in $pairs){ $v = @($pr | ForEach-Object { D $_ }); $last = $v.Count - 1; $done = $false
    if($t.Contains($v[$last])){ continue }
    for($i = $last - 1; $i -ge 0; $i--){ if($t.Contains($v[$i])){ $t = $t.Replace($v[$i],$v[$last]); $todo++; $done = $true; break } }
    if(-not $done){ Write-Host "NOT FOUND in ${rel}: $($v[0].Substring(0,[Math]::Min(60,$v[0].Length)))"; $script:ok=$false; return } }
  if($todo -eq 0){ Write-Host "Already applied: $rel"; return }
  Copy-Item $p "$p.hist.bak" -Force
  [IO.File]::WriteAllText($p,$t,(New-Object Text.UTF8Encoding($false))); Write-Host "Updated: $rel"
}
